00051 //
00052 //
00053 Surface::Surface(const std::string name, uint64_t checksum, const std::shared_ptr<Buffer> &buffer, unsigned offset, unsigned width,
00054                  unsigned height, unsigned stride)
00055     : name_(name), checksum_(checksum), buffer_(buffer), offset_(offset), width_(width), height_(height), stride_(stride) {}
00056 
00057 // Global debug state for surface dumping
00058 //
00059 static bool dump_surfaces = true;
00060 static std::map<std::string, std::unique_ptr<YUVWriter>> yuv_writers;
00061 
00062 void Surface::set_dump_surfaces(bool b) { dump_surfaces = b; }
00063 
00064 bool Surface::get_dump_surfaces() { return dump_surfaces; }
00065 
00066 // Dump surface as 8bit p420, with dummy chroma planes
00067 //
00068 void Surface::dump_p420(const std::string &name) const {
00069     if (!dump_surfaces)
00070         return;
00071 
00072     ImageDescription desc(IMAGE_FORMAT_YUV420P8, width(), height());
00073 
00074     if (yuv_writers.find(name) == yuv_writers.end())
00075         yuv_writers[name] = CreateYUVWriter(name, desc, true);
00076 
00077     Surface planes[3];
00078 
00079     if (bpp() == 1)
00080         // Just use base as bytes
00081         planes[0] = *this;
00082     else
00083         // Assume S87
00084         planes[0] = ConvertToU8().process(*this, 7);
00085 
00086     // Create a dummy surface for U&V
00087     auto sb = Surface::build_from<uint8_t>();
00088     // sb.reserve(width() / 2, height() / 2);
00089     sb.reserve(width() >> 1, height() >> 1);
00090     memset(sb.data(0, 0), 0x80, sb.width() * sb.height());
00091     planes[1] = planes[2] = sb.finish();
00092 
00093     yuv_writers[name]->write(Image(name, desc, 0, planes));
00094 }
00095 
00096 // Dump surface as 8bpp, 10bpp, 12bpp, or 14bpp with correct chroma subsampling and proper chroma planes
00097 //
00098 void Surface::dump_yuv(const std::string &name, Surface (&planes)[3], ImageDescription desc, bool decorate) const {
00099     if (desc.bit_depth() == 8) {
00100         Surface converted[3];
00101         if (yuv_writers.find(name) == yuv_writers.end())
00102             yuv_writers[name] = CreateYUVWriter(name, desc, decorate);
00103         for (unsigned p = 0; p < desc.num_planes(); p++)
00104             converted[p] = ConvertToU8().process(planes[p], 7);
00105         yuv_writers[name]->write(Image(name, desc, 0, converted));
00106     } else if (desc.bit_depth() == 10) {
00107         Surface converted[3];
00108         if (yuv_writers.find(name) == yuv_writers.end())
00109             yuv_writers[name] = CreateYUVWriter(name, desc, decorate);
00110         for (unsigned p = 0; p < desc.num_planes(); p++)
00111             converted[p] = ConvertToU16().process(planes[p], 5);
00112         yuv_writers[name]->write(Image(name, desc, 0, converted));
00113     } else if (desc.bit_depth() == 12) {
00114         Surface converted[3];
00115         if (yuv_writers.find(name) == yuv_writers.end())
00116             yuv_writers[name] = CreateYUVWriter(name, desc, decorate);
00117         for (unsigned p = 0; p < desc.num_planes(); p++)
00118             converted[p] = ConvertToU16().process(planes[p], 3);
00119         yuv_writers[name]->write(Image(name, desc, 0, converted));
00120     } else if (desc.bit_depth() == 14) {
00121         Surface converted[3];
00122         if (yuv_writers.find(name) == yuv_writers.end())
00123             yuv_writers[name] = CreateYUVWriter(name, desc, decorate);
00124         for (unsigned p = 0; p < desc.num_planes(); p++)
00125             converted[p] = ConvertToU16().process(planes[p], 1);
00126         yuv_writers[name]->write(Image(name, desc, 0, converted));
00127     } else {
00128         INFO("Image Format not supported %4d bpp", desc.bit_depth());
00129     }
00130 }
00131 
00132 // Dump surface as 8 or 16 bit Y
00133 //
00134 void Surface::dump(const std::string &name) const {
00135     if (!dump_surfaces)
00136         return;
00137 
00138     ImageFormat fmt = IMAGE_FORMAT_NONE;
00139     switch (bpp()) {
00140     case 2:
00141         fmt = IMAGE_FORMAT_Y16;
00142         break;
00143     case 1:
00144         fmt = IMAGE_FORMAT_Y8;
00145         break;
00146     default:
00147         assert(false);
00148     }
00149 
00150     ImageDescription desc(fmt, width(), height());
00151 
00152     if (yuv_writers.find(name) == yuv_writers.end())
00153         yuv_writers[name] = CreateYUVWriter(name, desc, true);
00154 
00155     Surface planes[3];
00156 
00157     planes[0] = *this;
00158     yuv_writers[name]->write(Image(name, desc, 0, planes));
00159 }
00160 
00161 // Dump array of layers/surfaces as 16 bit Y
00162 //
00163 void Surface::dump_layers(const Surface surface[], const std::string &name, const unsigned transform_block_size) {
00164     if (!dump_surfaces)
00165         return;
00166 
00167     CHECK(surface[0].bpp() == 2); // only 16 bit supported at the moment
00168     ImageDescription desc(IMAGE_FORMAT_Y16, surface[0].width() * transform_block_size, surface[0].height() * transform_block_size);
00169 
00170     if (yuv_writers.find(name) == yuv_writers.end())
00171         yuv_writers[name] = CreateYUVWriter(name, desc, true);
00172 
00173     Surface planes[3];
00174 
00175     if (transform_block_size == 2) {
00176         const auto src00_view = surface[0].view_as<int16_t>();
00177         const auto src01_view = surface[1].view_as<int16_t>();
00178         const auto src02_view = surface[2].view_as<int16_t>();
00179         const auto src03_view = surface[3].view_as<int16_t>();
00180 
00181         auto dst = Surface::build_from<int16_t>();
00182         dst.reserve(surface[0].width() * transform_block_size, surface[0].height() * transform_block_size);
00183 
00184         for (unsigned x = 0; x < surface[0].width(); x++) {
00185             for (unsigned y = 0; y < surface[0].height(); y++) {
00186                 dst.write(x * 2 + 0, y * 2 + 0, src00_view.read(x, y));
00187                 dst.write(x * 2 + 1, y * 2 + 0, src01_view.read(x, y));
00188                 dst.write(x * 2 + 0, y * 2 + 1, src02_view.read(x, y));
00189                 dst.write(x * 2 + 1, y * 2 + 1, src03_view.read(x, y));
00190             }
00191         }
00192         planes[0] = dst.finish();
00193     } else {
00194         const auto src00_view = surface[0].view_as<int16_t>();
00195         const auto src01_view = surface[1].view_as<int16_t>();
00196         const auto src02_view = surface[2].view_as<int16_t>();
00197         const auto src03_view = surface[3].view_as<int16_t>();
00198         const auto src04_view = surface[4].view_as<int16_t>();
00199         const auto src05_view = surface[5].view_as<int16_t>();
00200         const auto src06_view = surface[6].view_as<int16_t>();
00201         const auto src07_view = surface[7].view_as<int16_t>();
00202         const auto src08_view = surface[8].view_as<int16_t>();
00203         const auto src09_view = surface[9].view_as<int16_t>();
00204         const auto src10_view = surface[10].view_as<int16_t>();
00205         const auto src11_view = surface[11].view_as<int16_t>();
00206         const auto src12_view = surface[12].view_as<int16_t>();
00207         const auto src13_view = surface[13].view_as<int16_t>();
00208         const auto src14_view = surface[14].view_as<int16_t>();
00209         const auto src15_view = surface[15].view_as<int16_t>();
00210 
00211         auto dst = Surface::build_from<int16_t>();
00212         dst.reserve(surface[0].width() * transform_block_size, surface[0].height() * transform_block_size);
00213 
00214         for (unsigned x = 0; x < surface[0].width(); x++) {
00215             for (unsigned y = 0; y < surface[0].height(); y++) {
00216                 dst.write(x * 4 + 0, y * 4 + 0, src00_view.read(x, y));
00217                 dst.write(x * 4 + 1, y * 4 + 0, src01_view.read(x, y));
00218                 dst.write(x * 4 + 2, y * 4 + 0, src02_view.read(x, y));
00219                 dst.write(x * 4 + 3, y * 4 + 0, src03_view.read(x, y));
00220                 dst.write(x * 4 + 0, y * 4 + 1, src04_view.read(x, y));
00221                 dst.write(x * 4 + 1, y * 4 + 1, src05_view.read(x, y));
00222                 dst.write(x * 4 + 2, y * 4 + 1, src06_view.read(x, y));
00223                 dst.write(x * 4 + 3, y * 4 + 1, src07_view.read(x, y));
00224                 dst.write(x * 4 + 0, y * 4 + 2, src08_view.read(x, y));
00225                 dst.write(x * 4 + 1, y * 4 + 2, src09_view.read(x, y));
00226                 dst.write(x * 4 + 2, y * 4 + 2, src10_view.read(x, y));
00227                 dst.write(x * 4 + 3, y * 4 + 2, src11_view.read(x, y));
00228                 dst.write(x * 4 + 0, y * 4 + 3, src12_view.read(x, y));
00229                 dst.write(x * 4 + 1, y * 4 + 3, src13_view.read(x, y));
00230                 dst.write(x * 4 + 2, y * 4 + 3, src14_view.read(x, y));
00231                 dst.write(x * 4 + 3, y * 4 + 3, src15_view.read(x, y));
00232             }
00233         }
00234         planes[0] = dst.finish();
00235     }
00236 
00237     yuv_writers[name]->write(Image(name, desc, 0, planes));
00238 }
00239 
00240 void Surface::dump_image(const std::string &name) const {
00241     ImageFormat fmt = IMAGE_FORMAT_NONE;
00242     switch (bpp()) {
00243     case 2:
00244         fmt = IMAGE_FORMAT_Y16;
00245         break;
00246     case 1:
00247         fmt = IMAGE_FORMAT_Y8;
00248         break;
00249     default:
00250         assert(false);
00251     }
00252 
00253     ImageDescription desc(fmt, width(), height());
00254 
00255     auto writer = CreateYUVWriter(name, desc, true);
00256 
00257     Surface planes[3];
00258     planes[0] = *this;
00259 
00260     writer->write(Image(name, desc, 0, planes));
00261 }
00262 
00263 uint64_t Surface::checksum() const {
00264     if (!checksummed_) {
00265         SurfaceView<uint8_t> v(*this);
00266         checksum_ = crc64(0, v.data(), v.size());
00267         checksummed_ = true;
00268     }
00269 
00270     return checksum_;
00271 }
00272 
00273 } // namespace lctm
